function [b] = field_eci(r_eci, jd, gh, nmax)
%FIELD_ECI  The field [T] at an inertial position at a Julian date: to the Earth-fixed frame, geodetic
%   coordinates, IGRF in north-east-down, back to J2000.
%   r_eci: real[m][3] (passed in m)
%   jd: real[1] (passed a plain number)
%   gh: real[1][195] (passed a plain number)
%   nmax: int (passed a whole number)
%   returns b: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    b = zeros(3, 1);
    c = asils.alg.frames.eci2ecef(jd);
    re = [c(1, 1)*r_eci(1) + c(1, 2)*r_eci(2) + c(1, 3)*r_eci(3); c(2, 1)*r_eci(1) + c(2, 2)*r_eci(2) + c(2, 3)*r_eci(3); c(3, 1)*r_eci(1) + c(3, 2)*r_eci(2) + c(3, 3)*r_eci(3)];
    [lat, lon, h] = asils.alg.frames.geodetic(re);
    bn = asils.alg.frames.igrf_ned(gh, lat, lon, (h / 1000), nmax);
    bn(1) = (bn(1) * 1e-9);
    bn(2) = (bn(2) * 1e-9);
    bn(3) = (bn(3) * 1e-9);
    sl = sin(lat);
    cl = cos(lat);
    so = sin(lon);
    co = cos(lon);
    be = [(((((-(sl)) * co) * bn(1)) - (so * bn(2))) - ((cl * co) * bn(3))); (((((-(sl)) * so) * bn(1)) + (co * bn(2))) - ((cl * so) * bn(3))); ((cl * bn(1)) - (sl * bn(3)))];
    b = asils.alg.math.mat3t_vec(c, be);
end
